import {hairStyles,hairGeometry} from './pose-hair.js';
import {POSE_KEY,MAX_BYTES,MAX_PLACEMENTS,neutral,profiles,profileLabels,jointIds,endpoints,starters,starter,fk,euler,toEuler,rotate,add,project,unproject,viewCamera,aimJoint,solveEndpoint,enforcePins,mirror,validateState,blankLibrary,validateLibrary,saveRecord,mergeLibrary,applyRecord} from './pose-model.js';
const NS='http://www.w3.org/2000/svg';
function node(tag,attrs={},text){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;return e;}
export function drawRig(svg,state,width,height,selected='',floor=false){svg.replaceChildren();const f=fk(state),camera=viewCamera(state),p=id=>project(f[id].p,camera,width,height),point=v=>project(v,camera,width,height);
 const line=(a,b,color,width=5,dash=false)=>svg.append(node('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:color,'stroke-width':width,'stroke-linecap':'round',...(dash?{'stroke-dasharray':'5 5'}:{})}));
 if(floor){for(let i=-3;i<=3;i++){line(point([i,-2.6,-3]),point([i,-2.6,3]),'#454950',1);line(point([-3,-2.6,i]),point([3,-2.6,i]),'#454950',1);}}
 const plane=(ids,color)=>svg.append(node('polygon',{points:ids.map(id=>`${p(id).x},${p(id).y}`).join(' '),fill:color,stroke:'#aac9d7','stroke-width':1.5}));
 plane(['leftShoulder','rightShoulder','rightHip','leftHip'],'#47758b55');
 line(p('leftShoulder'),p('rightShoulder'),'#e7ba7e',4);line(p('leftHip'),p('rightHip'),'#e7ba7e',4);
 const joints=Object.values(f).filter(j=>j.parent).sort((a,b)=>p(a.id).z-p(b.id).z);
 for(const j of joints)line(p(j.parent),p(j.id),j.id.startsWith('left')?'#8fcbd7':j.id.startsWith('right')?'#c0b1ed':'#c6d6e1',j.id==='chest'?9:5);
 const hair=hairGeometry(state.hair).map(face=>{const points=face.map(v=>point(add(f.head.p,rotate(f.head.q,v.map(n=>n*state.profile.head)))));return {points,z:points.reduce((a,p)=>a+p.z,0)/3};}).filter(face=>face.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.z<11&&Math.abs(p.x)<1e5&&Math.abs(p.y)<1e5)).sort((a,b)=>a.z-b.z),headDepth=p('head').z;
 const drawHair=front=>{for(const face of hair){if((face.z>=headDepth)!==front)continue;svg.append(node('polygon',{points:face.points.map(p=>`${p.x},${p.y}`).join(' '),fill:front?'#5c8295':'#3d6071',stroke:front?'#c2dce5':'#87aab9','stroke-width':.55,'stroke-linejoin':'round','data-hair-face':front?'front':'back'}));}};
 drawHair(false);
 const head=p('head'),radius=state.profile.head*height/6*camera.zoom*head.factor;svg.append(node('ellipse',{cx:head.x,cy:head.y,rx:radius*.8,ry:radius,fill:'#344b5dcc',stroke:'#d3e1eb','stroke-width':2}));
 const nose=point(add(f.head.p,rotate(f.head.q,[0,0,state.profile.head*1.1])));line(head,nose,'#edbf86',2);drawHair(true);
 if(state.prop.kind!=='none'){const wrist=f[state.prop.hand],q=wrist.q,angle=state.prop.angle*Math.PI/180,dir=[Math.sin(angle),Math.cos(angle),0],end=point(add(wrist.p,rotate(q,dir.map(x=>x*state.prop.length)))),start=p(state.prop.hand);line(start,end,'#ecc388',state.prop.kind==='sword'?5:9);if(['hammer','box','object'].includes(state.prop.kind)){svg.append(node('rect',{x:end.x-20,y:end.y-12,width:40,height:24,rx:state.prop.kind==='object'?10:2,fill:'#ad895a77',stroke:'#ecc388','stroke-width':3}));}else{const t=.2,guard=point(add(wrist.p,rotate(q,dir.map(x=>x*t))));line({x:guard.x-12,y:guard.y},{x:guard.x+12,y:guard.y},'#ecc388',4);}}
 for(const id of jointIds){const a=p(id),pinned=!!state.pins[id];svg.append(node('circle',{cx:a.x,cy:a.y,r:id===selected?9:pinned?7:4.5,fill:id===selected?'#f0bd78':pinned?'#a3e5aa':'#203340',stroke:'#e0eaf0','stroke-width':1.5,'data-joint':id}));}
 if(selected&&f[selected]){const a=p(selected);svg.append(node('text',{x:Math.min(width-140,Math.max(8,a.x+14)),y:Math.max(20,a.y-14),fill:'#f5d7ae','font-size':13},selected.replace(/([A-Z])/g,' $1')));}
}
export function initPoseUI({$,blocked,beforeOpen,getContext,status,focus}){
 const dialog=$('pose-dialog'),studio=$('pose-preview'),overlay=$('pose-overlay');let draft=neutral(),selected='rightWrist',library=blankLibrary(),raw=null,storageError='',boardId=null,opened=false,drag=null,past=[],future=[],activeRecord='',overlayKey='';
 const error=e=>{$('pose-error').textContent=e?.message||String(e||'');};
 function read(){storageError='';try{raw=localStorage.getItem(POSE_KEY);if(raw&&raw.length>MAX_BYTES)throw Error('Oversized pose storage');library=raw?validateLibrary(JSON.parse(raw)):blankLibrary();}catch(e){library=blankLibrary();storageError='Pose storage unavailable; existing data preserved. Export/recover it before retrying. '+e.message;}return !storageError;}
 function write(next){if(storageError)throw Error(storageError);validateLibrary(next);if(localStorage.getItem(POSE_KEY)!==raw)throw Error('Pose library changed in another tab; close and reopen before saving');const text=JSON.stringify(next);localStorage.setItem(POSE_KEY,text);raw=text;library=next;}
 function remember(next){const valid=validateState(next);if(JSON.stringify(valid)===JSON.stringify(draft)){error('');render();return;}past.push(structuredClone(draft));if(past.length>50)past.shift();future=[];draft=valid;error('');render();}
 function edit(fn){try{remember(enforcePins(fn(structuredClone(draft))));}catch(e){error(e);render(false);}}
 function render(sync=true){if(!opened)return;const r=studio.getBoundingClientRect();drawRig(studio,draft,r.width,r.height,selected,true);$('pose-undo').disabled=!past.length;$('pose-redo').disabled=!future.length;$('pose-pin').disabled=!endpoints.includes(selected);$('pose-pin').textContent=draft.pins[selected]?'Unpin hand / foot':'Pin hand / foot';$('pose-joint').value=selected;
 if(sync){const angles=toEuler(draft.rotations[selected]);['x','y','z'].forEach((axis,i)=>$('pose-rot-'+axis).value=angles[i].toFixed(1));for(const key of Object.keys(profileLabels))$('pose-prop-'+key).value=draft.profile[key];for(const key of ['yaw','pitch','zoom','perspective','panX','panY'])$('pose-camera-'+key).value=draft.camera[key];for(const key of ['kind','hand','length','angle'])$('pose-object-'+key).value=draft.prop[key];for(const key of ['x','y','scale','angle','opacity'])$('pose-place-'+key).value=draft.placement[key];$('pose-visible').checked=draft.placement.visible;for(const key of ['style','volume','length','part','bangs'])$('pose-hair-'+key).value=draft.hair[key];}
 }
 function options(){const list=$('pose-saved');list.replaceChildren(new Option('Choose a saved preset',''));for(const r of library.records)list.add(new Option(`${r.name} · ${r.kind}`,r.id));list.value=activeRecord;$('pose-update').disabled=!activeRecord||!!storageError;$('pose-delete').disabled=!activeRecord||!!storageError;for(const id of ['pose-save','pose-apply','pose-import'])$(id).disabled=!!storageError;}
 function close(){if(drag){draft=drag.before;drag=null;}opened=false;dialog.close();focus();syncOverlay();}
 function open(){if(blocked())return;try{beforeOpen();const c=getContext();boardId=c.boardId;read();const stored=library.placements.find(r=>r.board===boardId);draft=stored?validateState(stored.state):neutral();if(!stored){draft.placement.x=c.center.x;draft.placement.y=c.center.y;}past=[];future=[];activeRecord='';opened=true;$('pose-starter').value='';dialog.showModal();options();error(storageError);render();$('pose-close').focus();}catch(e){opened=false;error(e);status(e.message,true);}}
 function syncOverlay(){const c=getContext();if(!c?.boardId)return;if(!opened&&c.boardId!==boardId){boardId=c.boardId;read();}const key=[c.boardId,c.view.x,c.view.y,c.view.scale,raw,storageError].join('|');if(key===overlayKey)return;overlayKey=key;const state=library.placements.find(r=>r.board===c.boardId)?.state;overlay.replaceChildren();if(!state||!state.placement.visible||storageError)return;const group=node('g'),p=state.placement;drawRig(group,state,600,600);group.setAttribute('transform',`translate(${c.view.x+p.x*c.view.scale} ${c.view.y+p.y*c.view.scale}) rotate(${p.angle}) scale(${c.view.scale*p.scale/100}) translate(-300 -300)`);group.setAttribute('opacity',p.opacity);overlay.append(group);}
 $('pose-open').onclick=open;$('pose-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 $('pose-starter').replaceChildren(new Option('Choose an action starter…',''),...starters.map(r=>new Option(r.name,r.id)));$('pose-starter').onchange=()=>{const id=$('pose-starter').value;if(id)edit(s=>starter(id,s));$('pose-starter').value='';};
 $('pose-joint').replaceChildren(...jointIds.map(id=>new Option(id.replace(/([A-Z])/g,' $1'),id)));$('pose-joint').onchange=()=>{selected=$('pose-joint').value;render();};
 for(const axis of ['x','y','z'])$('pose-rot-'+axis).onchange=()=>edit(s=>{s.rotations[selected]=euler(...['x','y','z'].map(k=>Number($('pose-rot-'+k).value)));return s;});
 $('pose-pin').onclick=()=>edit(s=>{if(!endpoints.includes(selected))return s;if(s.pins[selected])delete s.pins[selected];else s.pins[selected]=fk(s)[selected].p;return s;});
 $('pose-mirror').onclick=()=>edit(s=>mirror(s));
 $('pose-undo').onclick=()=>{if(!past.length)return;future.push(draft);draft=past.pop();error('');render();};$('pose-redo').onclick=()=>{if(!future.length)return;past.push(draft);draft=future.pop();error('');render();};
 $('pose-hair-style').replaceChildren(...Object.entries(hairStyles).map(([id,label])=>new Option(label,id)));
 for(const key of ['style','volume','length','part','bangs'])$('pose-hair-'+key).onchange=()=>edit(s=>{s.hair[key]=key==='style'?$('pose-hair-'+key).value:Number($('pose-hair-'+key).value);return s;});
 $('pose-head-view').onclick=()=>edit(s=>{s.camera.focus='head';s.camera.zoom=2.5;s.camera.panX=s.camera.panY=0;return s;});
 $('pose-body-view').onclick=()=>edit(s=>{s.camera.focus='body';s.camera.zoom=1;s.camera.panX=s.camera.panY=0;return s;});
 $('pose-profile').onchange=()=>edit(s=>{s.profile={...profiles[$('pose-profile').value]};return s;});
 for(const key of Object.keys(profileLabels))$('pose-prop-'+key).onchange=()=>edit(s=>{s.profile[key]=Number($('pose-prop-'+key).value);return s;});
 for(const key of ['yaw','pitch','zoom','perspective','panX','panY'])$('pose-camera-'+key).onchange=()=>edit(s=>{s.camera[key]=Number($('pose-camera-'+key).value);return s;});
 $('pose-camera-reset').onclick=()=>edit(s=>{s.camera={...neutral().camera};return s;});
 for(const key of ['kind','hand','length','angle'])$('pose-object-'+key).onchange=()=>edit(s=>{s.prop[key]=['kind','hand'].includes(key)?$('pose-object-'+key).value:Number($('pose-object-'+key).value);return s;});
 for(const key of ['x','y','scale','angle','opacity'])$('pose-place-'+key).onchange=()=>edit(s=>{s.placement[key]=Number($('pose-place-'+key).value);return s;});$('pose-visible').onchange=()=>edit(s=>{s.placement.visible=$('pose-visible').checked;return s;});
 $('pose-saved').onchange=()=>{activeRecord=$('pose-saved').value;const r=library.records.find(r=>r.id===activeRecord);if(r){$('pose-name').value=r.name;$('pose-save-kind').value=r.kind;}options();};
 $('pose-load').onclick=()=>{const r=library.records.find(r=>r.id===activeRecord);if(!r)return error('Choose a saved preset');edit(s=>applyRecord(s,r));};
 function save(update){try{const id=update?activeRecord:crypto.randomUUID(),next=saveRecord(library,draft,{id,name:$('pose-name').value,kind:$('pose-save-kind').value,update});write(next);activeRecord=id;options();error('');$('pose-message').textContent='Saved on this device. Download a pose backup for portability.';}catch(e){error(e);}}
 $('pose-save').onclick=()=>save(false);$('pose-update').onclick=()=>save(true);$('pose-delete').onclick=()=>{try{const l=structuredClone(library);l.records=l.records.filter(r=>r.id!==activeRecord);write(l);activeRecord='';options();error('');}catch(e){error(e);}};
 function download(data,name){const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('pose-backup').onclick=()=>download(storageError?(raw||''):JSON.stringify(library,null,2),'unruly-poses.json');
 $('pose-import').onchange=async()=>{const file=$('pose-import').files[0];try{if(!file)return;if(file.size>MAX_BYTES)throw Error('Pose library exceeds 512 KiB');const next=mergeLibrary(library,JSON.parse(await file.text()),()=>crypto.randomUUID());write(next);options();error('');$('pose-message').textContent='Imported saved presets with fresh IDs. Existing presets and board references preserved.';}catch(e){error(e);}finally{$('pose-import').value='';}};
 $('pose-apply').onclick=()=>{try{const s=validateState(draft),l=structuredClone(library),idx=l.placements.findIndex(r=>r.board===boardId);if(idx<0&&l.placements.length>=MAX_PLACEMENTS)throw Error('32 board references reached; remove one before adding another');const r={board:boardId,state:s};if(idx<0)l.placements.push(r);else l.placements[idx]=r;write(l);close();status('Pose reference applied · excluded from artwork exports · edit via Actions → Pose references');}catch(e){error(e);}};
 $('pose-remove').onclick=()=>{try{const l=structuredClone(library);l.placements=l.placements.filter(r=>r.board!==boardId);write(l);close();status('Pose reference removed; artwork unchanged');}catch(e){error(e);}};
 const wrap=v=>((v+180)%360+360)%360-180;
 studio.addEventListener('pointerdown',e=>{if(e.button!==0||drag)return;const r=studio.getBoundingClientRect(),x=e.clientX-r.x,y=e.clientY-r.y,nearest=jointIds.map(id=>({id,p:project(fk(draft)[id].p,viewCamera(draft),r.width,r.height)})).map(j=>({...j,d:Math.hypot(j.p.x-x,j.p.y-y)})).sort((a,b)=>a.d-b.d)[0];drag={id:e.pointerId,before:structuredClone(draft),x,y,width:r.width,height:r.height,joint:nearest.d<22?nearest.id:null,depth:nearest.p.z};if(drag.joint)selected=drag.joint;try{studio.setPointerCapture(e.pointerId);}catch{}e.preventDefault();render();});
 studio.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const r=studio.getBoundingClientRect(),x=e.clientX-r.x,y=e.clientY-r.y;try{let s=structuredClone(drag.before);if(drag.joint){if(drag.joint==='pelvis')return;const target=unproject(x,y,drag.depth,viewCamera(s),drag.width,drag.height);if(endpoints.includes(drag.joint)){if(s.pins[drag.joint])s.pins[drag.joint]=target;s=solveEndpoint(s,drag.joint,target);}else s=aimJoint(s,drag.joint,target);s=enforcePins(s);}else{s.camera.yaw=wrap(s.camera.yaw+(x-drag.x)*.5);s.camera.pitch=wrap(s.camera.pitch+(y-drag.y)*.5);}draft=validateState(s);error('');render();}catch(e){error(e);}});
 function end(e,cancel=false){if(!drag||e.pointerId!==drag.id)return;const before=drag.before;drag=null;if(cancel)draft=before;else if(JSON.stringify(before)!==JSON.stringify(draft)){past.push(before);if(past.length>50)past.shift();future=[];}render();}
 studio.addEventListener('pointerup',e=>end(e));studio.addEventListener('pointercancel',e=>end(e,true));studio.addEventListener('lostpointercapture',e=>end(e,true));
 new ResizeObserver(()=>{render();syncOverlay();}).observe(studio);
 window.addEventListener('storage',e=>{if(e.key!==POSE_KEY&&e.key!==null)return;if(opened)error('Pose library changed in another tab; close and reopen before saving');else{read();syncOverlay();}});
 return {hasReference:()=>!storageError&&!!library.placements.find(r=>r.board===getContext()?.boardId)?.state.placement.visible,editing:()=>opened,sync:syncOverlay,key:e=>{if(!opened)return false;if(e.key==='Escape'){e.preventDefault();close();}return true;}};
}
